<docs>
Use this screen at the end of your experiment to submit the data to the server.
You can provide the submission URL to the Experiment component.
</docs>

<template>
  <Screen v-if="!$magpie.debug" title="Submitting">
    <Slide>
      <p>{{ $t('screens.SubmitResultsScreen.waiting') }}</p>
      <Wait :time="0" @done="submit()" />
    </Slide>

    <Slide>
      <p v-if="!error">
        {{ $t('screens.SubmitResultsScreen.done') }}
      </p>

      <div v-else>
        <p>{{ $t('screens.SubmitResultsScreen.error') }}</p>

        <p>
          {{ $t('screens.SubmitResultsScreen.contact') }}
          <a :href="'mailto:' + $magpie.contactEmail">
            {{ $magpie.contactEmail }}
          </a>.
        </p>

        <p v-text="error" />
      </div>
    </Slide>
  </Screen>

  <DebugResultsScreen v-else />
</template>

<script>
import Screen from '../Screen';
import Wait from '../helpers/Wait';
import DebugResultsScreen from './DebugResultsScreen';
import Slide from '../Slide';

export default {
  name: 'SubmitResultsScreen',

  components: {
    Screen,
    Slide,
    Wait,
    DebugResultsScreen
  },

  data() {
    return {
      error: null
    };
  },

  methods: {
    async submit() {
      try {
        // Wait until the data have been successfully submitted.
        await this.$magpie.submit();

        // Show the successful-submission slide.
        this.$magpie.nextSlide();

        // Redirect after displaying the completion message for three seconds.
        window.setTimeout(() => {
          this.redirectToCompletionUrl();
        }, 3000);
      } catch (err) {
        this.error =
          err instanceof Error
            ? err.message
            : String(err);

        // Show the error on the second slide without redirecting.
        this.$magpie.nextSlide();
      }
    },

    disableUnloadWarning() {
      const experiment = this.$magpie.experiment;

      if (
        experiment &&
        typeof experiment.disableBeforeUnload === 'function'
      ) {
        experiment.disableBeforeUnload();
      }
    },

    redirectToCompletionUrl() {
      // Prolific
      if (
        this.$magpie.mode === 'prolific' &&
        this.$magpie.completionUrl
      ) {
        this.disableUnloadWarning();
        window.location.assign(this.$magpie.completionUrl);
        return;
      }

      // Sona
      if (this.$surveyCode) {
        const url = new URL(
          'https://uni-tuebingen.sona-systems.com/webstudy_credit.aspx'
        );

        url.searchParams.set('experiment_id', '805');
        url.searchParams.set(
          'credit_token',
          '77d68adf3c724c50a4ac5e59ed528792'
        );
        url.searchParams.set(
          'survey_code',
          this.$surveyCode
        );

        this.disableUnloadWarning();
        window.location.assign(url.toString());
      }
    }
  }
};
</script>
